<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {RouterLink} from 'vue-router'
import {getQuality,type QualityData} from '../services/admin.ts'
const data=ref<QualityData|null>(null),busy=ref(false),error=ref(''),field=ref(''),query=ref(''),page=ref(1),scope=ref(0)
const labels:Record<string,string>={abstract:'摘要',doi:'DOI',authors:'作者',source:'来源'}
const issues=computed(()=>data.value?.issues.filter(p=>(!field.value||p.missing.includes(field.value))&&(!query.value||p.title.toLowerCase().includes(query.value.toLowerCase())))??[])
const selected=computed(()=>data.value?.coverage[scope.value])
async function load(){busy.value=true;error.value='';try{data.value=await getQuality();page.value=1;scope.value=0}catch(e){error.value=String(e)}finally{busy.value=false}}
function download(){if(!data.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(data.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='a-data-quality.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(load)
</script>
<template><section class="standard-page quality-page"><div class="page-heading"><div><div class="eyebrow">DATA MANAGEMENT</div><h1>数据质量</h1><p>核对当前有效论文的信息缺失及正式采集覆盖。</p></div><RouterLink class="button button-secondary" to="/admin/overview">← 返回数据概览</RouterLink></div><p v-if="busy" role="status">正在核对数据质量…</p><p v-if="error" role="alert">{{error}}</p><div class="actions"><button class="button button-secondary" :disabled="busy" @click="load">刷新质量</button><button class="button button-secondary" :disabled="!data||busy" @click="download">导出质量报告</button></div><template v-if="data"><section class="panel"><h2>当前有效论文 {{data.total_papers.toLocaleString()}} 篇 · 信息待补充 {{data.issue_count}} 篇</h2><div class="actions"><label>缺失字段<select v-model="field" class="form-input" aria-label="缺失字段" @change="page=1"><option value="">全部</option><option v-for="(label,key) in labels" :value="key" :key="key">{{label}}</option></select></label><label>论文标题<input v-model="query" class="form-input" aria-label="质量论文标题" @input="page=1"/></label></div><p v-if="!issues.length">没有符合条件的缺失记录。</p><article v-for="p in issues.slice((page-1)*20,page*20)" :key="p.id"><strong>{{p.title}}</strong><p>{{p.venue}} {{p.year}} · 缺少 {{p.missing.map(f=>labels[f]??f).join('、')}}</p></article><div class="actions"><button class="text-button" :disabled="page<=1" @click="page--">上一页</button><span>第 {{page}} / {{Math.max(1,Math.ceil(issues.length/20))}} 页</span><button class="text-button" :disabled="page*20>=issues.length" @click="page++">下一页</button></div></section><section class="panel"><h2>正式采集覆盖与缺失明细</h2><p>正式采集库与当前页面数据库分别核对；覆盖率以冻结官方目录为分母。</p><select v-if="data.coverage.length" v-model.number="scope" class="form-input" aria-label="覆盖会议年度"><option v-for="(c,i) in data.coverage" :key="i" :value="i">{{c.venue??c.scope}} {{c.year??''}}</option></select><p v-else>本机尚无正式采集覆盖报告。</p><template v-if="selected"><p v-if="selected.error" role="alert">{{selected.error}}</p><template v-else><p>官方目录 {{selected.baseline_expected_papers}} · 匹配 {{selected.matched_papers}} · 覆盖率 {{(selected.coverage_ratio*100).toFixed(2)}}%</p><p>未匹配 {{selected.missing?.length??0}} 条，需核对标题或来源；不自动计入覆盖。</p><div class="missing-list"><article v-for="(p,i) in selected.missing" :key="i"><strong>{{p.title}}</strong><p>{{p.reason}}</p><a v-if="/^https?:\/\//.test(p.source_url??'')" :href="p.source_url" target="_blank" rel="noopener noreferrer">官方来源 ↗</a></article></div></template></template></section></template></section></template>
<style scoped>.quality-page .panel{padding:24px;margin:18px 0}.quality-page h2{font-size:16px}.quality-page p{font-size:12px;color:#789099;line-height:1.8;margin:12px 0}.quality-page article{padding:14px 0;border-bottom:1px solid #e1eae9;font-size:12px;overflow-wrap:anywhere}.quality-page label{font-size:12px}.quality-page .form-input{display:block;margin-top:7px;max-width:100%}.actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:18px 0;font-size:12px}.missing-list{max-height:450px;overflow:auto}.quality-page a{color:#218575}@media(max-width:600px){.quality-page .page-heading{flex-direction:column}.quality-page .panel{padding:16px}}</style>
